-- 점검 문제 갱신 (핵심 낱말 keywords 포함)
-- 자동 생성: scripts/build-keywords-sql.mjs
--
-- works.questions 만 갈아 끼운다. 본문·주석·해설은 건드리지 않으므로
-- 이미 올려 둔 작품에 낱말만 얹고 싶을 때 이 파일을 쓰면 된다.

-- 배비장전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"배 비장은 제주에 가기 전과 도착한 뒤에 각각 어떤 말과 행동을 했나요? 그것이 뒤에 어떤 구실을 하는지 함께 써 보세요.","sampleAnswer":"떠나기 전 어머니와 아내에게 여자에게 마음을 빼앗기지 않겠다고 다짐했고, 제주에 도착해서는 애랑에게 모든 것을 주고 앞니까지 뽑아 준 정 비장을 비웃었으며, 목사 앞에서는 흔들리면 목을 베라고까지 했습니다. 이렇게 스스로 높이 세워 둔 말들이 나중에 하나씩 무너지면서 웃음이 커지도록 짜여 있습니다.","keywords":["정 비장","애랑"]},{"position":1,"type":"short_answer","prompt":"궤 속에 갇힌 배 비장은 어떻게 행동했고, 궤에서 나온 뒤에는 무엇을 했나요?","sampleAnswer":"톱질 소리를 듣자 스스로 소리쳐 자기가 안에 있음을 알리며 살려 달라고 애원했고, 궤가 바다에 던져지는 줄 알고 겁에 질렸습니다. 자물쇠가 열리자 눈을 감은 채 기어 나와 두 팔을 허우적거리며 헤엄치는 시늉을 했는데, 눈을 떠 보니 관아 사람들이 가득한 동헌 마당이었습니다.","keywords":["헤엄","동헌"]},{"position":2,"type":"short_answer","prompt":"이 이야기에서 계획을 짜고 이끄는 사람은 누구인가요? 그 점이 어떤 의미를 갖는지 함께 써 보세요.","sampleAnswer":"목사가 말을 꺼냈지만 실제로 계획을 짜고 실행하는 사람은 기생 애랑과 방자입니다. 신분으로는 가장 아래에 있는 두 사람이 양반인 배 비장을 손바닥 위에 올려놓고 움직이는 셈이어서, 신분이 곧 사람의 됨됨이나 지혜를 정하지 않는다는 것을 보여 줍니다.","keywords":["애랑","방자"]},{"position":3,"type":"essay","prompt":"배 비장의 잘못은 마음이 흔들린 것이었을까요, 아니면 겪어 보지도 않은 일을 두고 자신을 장담한 것이었을까요? 자신의 생각을 써 보세요.","rubric":"작품이 겨누는 것이 욕망 자체가 아니라 위선과 자기 과신이라는 점을 짚었는지, 그리고 그 생각을 작품 속 근거나 자기 경험과 연결해 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'baebijang';

-- 박씨전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"박씨가 뒤뜰에 지은 집의 이름은 무엇이며, 그 이름에는 어떤 뜻이 담겨 있나요?","sampleAnswer":"피화당(避禍堂)입니다. ''화(禍)를 피하는 집''이라는 뜻으로, 실제로 병자호란 때 이 집에 심어 둔 나무들이 진법으로 작용하여 청나라 군사를 막아 내는 곳이 되었습니다.","keywords":["피화당"]},{"position":1,"type":"short_answer","prompt":"허물을 벗고 아름다워진 박씨에게 시백이 용서를 빌자, 박씨는 무엇이라고 대답했나요? 그 말에 담긴 뜻은 무엇일까요?","sampleAnswer":"''저는 그때나 지금이나 같은 사람이고, 다만 서방님의 눈이 달라졌을 뿐''이라고 대답했습니다. 사람의 됨됨이는 변한 것이 없는데 겉모습만 보고 사람을 판단했던 시백의 잘못을 조용히 지적한 말입니다.","keywords":["같은 사람","겉모습"]},{"position":2,"type":"short_answer","prompt":"실제 병자호란에서 조선은 청나라에 크게 패했습니다. 그런데도 작품에서는 박씨가 용골대를 무릎 꿇리는 것으로 그렸습니다. 그 까닭은 무엇일까요?","sampleAnswer":"현실에서는 나라가 짓밟히고 백성이 끌려가는 참담한 패배를 겪었기 때문에, 이야기 속에서라도 오랑캐를 물리치고 백성을 되찾는 통쾌한 승리를 그려 상처받은 마음을 위로하고자 한 것입니다.","keywords":["패배","승리"]},{"position":3,"type":"essay","prompt":"조정의 신하들은 박씨의 경고를 ''여자의 말''이라며 무시했습니다. 사람의 말을 그 사람이 누구인가에 따라 다르게 받아들인 셈입니다. 이런 일이 오늘날에도 있다고 생각하나요? 자신의 생각을 써 보세요.","rubric":"작품 속 편견의 문제를 이해했는지, 그리고 그것을 오늘의 경험이나 사회 현상과 연결해 자기 생각을 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'bakssi';

-- 채봉감별곡
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"김 진사는 왜 딸의 혼약을 깨려 했나요? 그리고 채봉은 어떻게 대응했나요?","sampleAnswer":"서울 허 판서 댁에 딸을 첩으로 보내면 과천 현감 자리를 얻을 수 있다는 생각에서였습니다. 채봉은 이미 혼약한 몸이라며 거부하고, ''약속이 그깟 것이면 벼슬은 무엇이겠습니까'', ''사려는 것이 벼슬이라면 파시는 것은 무엇입니까''라고 되물었으며, 서울로 가는 길에서 몰래 빠져나와 평양으로 돌아왔습니다.","keywords":["벼슬","혼약"]},{"position":1,"type":"short_answer","prompt":"옥에 갇힌 아버지를 구하기 위해 채봉이 택한 방법은 무엇이었나요? 그 선택에 담긴 아이러니를 함께 써 보세요.","sampleAnswer":"스스로 기생집을 찾아가 기적에 이름을 올리고 받은 몸값을 서울로 보내 아버지를 풀려나게 했습니다. 자기를 팔아 벼슬을 사려던 아버지를, 자기가 스스로를 팔아 구했다는 점에서 아프고 씁쓸한 아이러니가 있습니다.","keywords":["기생","몸값"]},{"position":2,"type":"short_answer","prompt":"채봉이 장필성과 다시 만나게 된 결정적인 계기는 무엇이었나요?","sampleAnswer":"가을밤에 스스로 지어 부른 「추풍감별곡」을 평양 감사 이보국이 듣고 사연을 물어보게 되면서입니다. 감사가 장필성을 찾아 이방으로 삼고 두 사람을 만나게 해 주었으므로, 결국 채봉을 구한 것은 채봉 자신의 글이었습니다.","keywords":["추풍감별곡","장필성"]},{"position":3,"type":"essay","prompt":"「춘향전」의 춘향은 옥에서 어사를 기다렸고, 채봉은 스스로 몸값을 만들고 제 글로 길을 열었습니다. 백 년쯤의 시차를 두고 나온 두 작품의 여성 인물이 이렇게 다른 까닭은 무엇일까요? 자신의 생각을 써 보세요.","rubric":"두 인물이 문제를 푸는 방식의 차이를 정확히 짚었는지, 그 차이를 시대 변화(신분제의 동요, 초자연적 장치의 퇴조 등)와 연결해 설명했는지, 그리고 자기 생각을 근거와 함께 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'chaebong';

-- 창선감의록
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"이 집안의 갈등이 어디에서 비롯되었는지, 아버지 화욱의 결정과 연결해 설명해 보세요.","sampleAnswer":"화욱이 맏이 화춘 대신 막내 화진에게 집안을 맡기라는 뜻을 남긴 데서 비롯됩니다. 밀려난 심씨와 화춘의 미움이 화진에게 쏠렸고, 아버지가 죽고 화진의 생모 정씨도 없는 상황에서 화진에게는 편들어 줄 사람이 없었습니다. 여기에 화춘의 첩 조씨가 들어와 없는 말을 지어내면서 집안이 무너집니다.","keywords":["화욱","화진"]},{"position":1,"type":"short_answer","prompt":"화진은 국문을 받으면서도 집안에서 벌어진 일을 말하지 않습니다. 이 선택을 어떻게 볼 수 있을까요? 두 가지 시각으로 써 보세요.","sampleAnswer":"한편으로는 어리석은 선택입니다. 사실을 밝히면 살 수 있었고, 죄 없는 자기가 죽는 것은 정의롭지도 않습니다. 다른 한편으로는 이 인물의 됨됨이를 그대로 보여 주는 선택입니다. 집안의 허물을 밖에 내지 않겠다는 원칙을 목숨이 걸린 자리에서도 지켰기 때문입니다. 제목의 ''창선''이 가리키는 것이 바로 이 대목입니다.","keywords":["집안","허물"]},{"position":2,"type":"short_answer","prompt":"이 작품의 결말은 「사씨남정기」·「장화홍련전」과 어떻게 다른가요?","sampleAnswer":"사씨남정기의 교씨와 장화홍련전의 계모는 처형됩니다. 그러나 창선감의록에서는 화진이 임금 앞에 엎드려 계모와 형의 벌을 거두어 달라 청하고, 심씨는 뉘우치며 화춘도 아우 앞에 무릎을 꿇습니다. 악인을 없애는 것이 아니라 사람으로 되돌리는 결말입니다.","keywords":["사씨남정기","처형"]},{"position":3,"type":"essay","prompt":"자기를 죽이려 한 사람을 용서하는 화진의 선택에 동의하나요? 악인을 벌하는 결말과 용서하는 결말 가운데 어느 쪽이 더 나은 이야기라고 생각하는지, 까닭과 함께 써 보세요.","rubric":"두 결말 방식의 차이를 정확히 파악했는지, 그리고 자기 판단에 대해 근거를 세웠는지를 봅니다. 어느 쪽을 고르든 정답으로 봅니다."}]'::jsonb
  WHERE slug = 'changseon';

-- 최척전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"정유재란으로 최척의 가족은 어떻게 흩어졌나요? 세 사람이 각각 어디로 가게 되었는지 써 보세요.","sampleAnswer":"남원성이 함락되면서 온 식구가 흩어졌습니다. 최척은 지리산으로 피했다가 명나라 장수를 따라 중국으로 건너갔고, 옥영은 왜적에게 붙들려 일본으로 끌려가 남장을 하고 지냈으며, 어린 아들 몽석은 할아버지와 함께 산속에 숨어 살아남았습니다.","keywords":["일본","중국"]},{"position":1,"type":"short_answer","prompt":"안남 바닷가에서 최척과 옥영은 어떻게 서로를 알아보았나요?","sampleAnswer":"달 밝은 밤 최척이 뱃전에서 고향에서 늘 불던 피리 가락을 불자, 옆 배에 있던 옥영이 그 소리를 알아듣고 지난날 함께 주고받던 시를 읊었습니다. 그 시를 들은 최척이 피리를 멈추고 배를 옮겨 가 두 사람이 만나게 되었습니다.","keywords":["피리","옥영"]},{"position":2,"type":"short_answer","prompt":"최척전에는 홍길동전이나 박씨전과 달리 도술이나 신령한 힘이 거의 나오지 않습니다. 그 대신 무엇이 인물들을 다시 만나게 하나요?","sampleAnswer":"피리 가락과 함께 주고받던 시, 우연히 같은 항구에 배를 대게 된 하룻밤, 그리고 포로 막사에서 나눈 ''고향이 어디냐''는 평범한 물음입니다. 초자연적인 힘이 아니라 함께 보낸 시간의 흔적과 우연이 재회를 만들어 냅니다.","keywords":["피리","우연"]},{"position":3,"type":"essay","prompt":"이 작품에서 적군인 늙은 병사는 ''나도 자식을 전쟁에 보내고 소식을 모른다''며 두 사람을 놓아줍니다. 전쟁을 다룬 다른 작품(예: 박씨전)과 견주어, 이 장면이 어떤 점에서 다른지 자신의 생각을 써 보세요.","rubric":"적을 물리치는 통쾌함으로 가는 대신 전쟁의 피해자라는 공통점에 주목한다는 차이를 짚었는지, 그리고 그 차이에 대한 자기 생각을 근거와 함께 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'choecheok';

-- 춘향전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"변학도가 춘향에게 수청을 들라고 요구한 근거는 무엇이었나요? 그리고 춘향은 어떤 말로 이를 거절했나요?","sampleAnswer":"기생의 딸이니 당연히 기생이며 사또의 명을 따라야 한다는 것이 변학도의 생각이었습니다. 춘향은 ''충신은 두 임금을 섬기지 아니하고, 열녀는 두 지아비를 섬기지 아니한다''며 이미 지아비를 정한 몸이므로 따를 수 없다고 거절했습니다.","keywords":["기생","거절"]},{"position":1,"type":"short_answer","prompt":"이몽룡이 잔치 자리에서 지은 시 ''금준미주는 천인혈이요, 옥반가효는 만성고라''는 무슨 뜻이며 무엇을 비판하고 있나요?","sampleAnswer":"''금 술잔의 맛있는 술은 천 사람의 피요, 옥쟁반의 좋은 안주는 만백성의 기름이라''는 뜻입니다. 벼슬아치들이 누리는 화려한 잔치가 사실은 백성을 쥐어짜서 마련한 것임을 지적하며 지배층의 사치와 수탈을 비판하고 있습니다.","keywords":["백성","비판"]},{"position":2,"type":"short_answer","prompt":"암행어사가 된 이몽룡은 왜 곧바로 신분을 밝히지 않고 일부러 거지 행색을 하고 다녔을까요?","sampleAnswer":"암행어사임을 미리 밝히면 벼슬아치들이 잘못을 감추고 백성들도 사실대로 말하지 않을 것이기 때문입니다. 몰래 다녀야 고을의 참모습과 백성들의 진짜 사정을 들을 수 있으므로 거지 행색으로 다녔습니다.","keywords":["암행어사","백성"]},{"position":3,"type":"essay","prompt":"춘향은 매를 맞으면서도 끝까지 뜻을 굽히지 않았습니다. 오늘날에도 힘 있는 사람의 부당한 요구를 거절하기는 쉽지 않습니다. 여러분이라면 어떻게 했을 것 같은지, 그리고 그런 상황에서 사람을 버티게 하는 힘은 무엇이라고 생각하는지 써 보세요.","rubric":"정답이 있는 문제가 아닙니다. 자신의 생각을 솔직하게 밝히고, 작품 속 춘향의 태도나 자신의 경험·주변 사례와 연결해 설명했는지를 봅니다."}]'::jsonb
  WHERE slug = 'chunhyang';

-- 취유부벽정기
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"부벽정에 오른 홍생은 무엇을 보고 어떤 감정을 느꼈나요?","sampleAnswer":"달빛 아래 무너진 성벽과 풀만 우거진 옛 궁궐 터를 보았습니다. 한때 나라의 도읍이던 곳이 빈 언덕이 된 것을 보며, 사람의 한평생도 나라도 결국 사라진다는 덧없음을 느끼고 시를 여섯 수나 읊었습니다. 이러한 정서를 회고(懷古)라고 합니다.","keywords":["궁궐","덧없"]},{"position":1,"type":"short_answer","prompt":"여인은 자신을 누구라고 밝혔나요? 그리고 그 설정이 이야기에서 어떤 구실을 하나요?","sampleAnswer":"기자조선 기씨의 딸로, 위만이 쳐들어와 나라를 빼앗을 때 절개를 지키려다 목숨을 끊고 선녀가 되었다고 밝혔습니다. 천 년도 더 된 옛사람이므로, 홍생은 책으로만 읽던 역사를 그 시대를 산 사람의 입으로 직접 듣게 됩니다. 사라진 나라를 눈앞에 불러내는 구실을 하는 것입니다.","keywords":["기자조선","선녀"]},{"position":2,"type":"short_answer","prompt":"이 작품에서 홍생과 여인을 이어 준 것은 무엇인가요? 「만복사저포기」와 견주어 설명해 보세요.","sampleAnswer":"두 사람을 이어 준 것은 시, 곧 글재주와 역사에 대한 마음입니다. 여인은 홍생의 시를 듣고 나타났고 그 시에 감탄했으며, 두 사람은 밤새 시만 주고받다 헤어집니다. 「만복사저포기」에서 양생과 여인이 부부의 인연을 맺고 사흘을 함께 지낸 것과 달리, 이 작품의 만남은 정신적인 교류에 머뭅니다.","keywords":["시","만복사저포기"]},{"position":3,"type":"essay","prompt":"홍생은 병으로 죽은 것이 아니라 스스로 목욕하고 옷을 갈아입은 뒤 자리에 누워 세상을 떠납니다. 다섯 살에 신동으로 불렸으나 평생 벼슬을 마다하고 떠돈 김시습의 삶과 겹쳐, 이 결말이 무엇을 말한다고 생각하는지 써 보세요.","rubric":"''알아주는 이를 만난 뒤 이곳에 머물지 못한다''는 구조를 파악했는지, 작가의 삶과 연결해 해석했는지, 그리고 자기 생각을 근거와 함께 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'chwiyu';

-- 구운몽
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"성진이 인간 세상으로 내려가게 된 까닭은 무엇인가요?","sampleAnswer":"용궁에서 술을 마시고 돌아오는 길에 팔선녀와 마주친 뒤, 벼슬에 올라 이름을 떨치고 아름다운 아내를 얻는 세속의 부귀영화를 그리워하며 마음이 어지러워졌기 때문입니다. 육관대사는 그 마음을 알고 인간 세상에서 직접 겪어 보게 했습니다.","keywords":["팔선녀","부귀"]},{"position":1,"type":"short_answer","prompt":"양소유는 부족한 것 없이 모든 것을 이루었는데도 누각에서 눈물을 흘립니다. 그가 깨달은 것은 무엇인가요?","sampleAnswer":"천하를 호령하던 진시황과 한무제도 결국 무덤 속 한 줌 흙이 되었듯, 자신이 누리는 부귀영화도 백 년 뒤에는 아무것도 남지 않으리라는 것입니다. 사람의 한평생이 꿈결처럼 덧없다는 깨달음입니다.","keywords":["부귀","덧없"]},{"position":2,"type":"short_answer","prompt":"육관대사는 왜 성진을 곧바로 꾸짖지 않고 인간 세상에서 한평생을 겪게 했을까요?","sampleAnswer":"말로 타이르는 것만으로는 마음속 욕망이 사라지지 않기 때문입니다. 바라던 것을 실컷 누려 보고 그것이 덧없음을 스스로 깨달아야 참된 깨달음이 된다고 보았기 때문입니다.","keywords":["깨달","스스로"]},{"position":3,"type":"essay","prompt":"양소유는 원하던 것을 모두 이루고도 허무함을 느꼈습니다. 여러분은 무엇을 이루면 행복할 것 같나요? 그리고 그것을 다 이룬 뒤에도 행복이 이어질지 자신의 생각을 써 보세요.","rubric":"작품이 던지는 ''성취와 행복''의 문제를 이해했는지, 그리고 자기 삶과 연결해 생각을 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'guunmong';

-- 광문자전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"거지 아이들에게 쫓겨난 광문은 그 뒤에 무엇을 했나요? 그 행동에서 알 수 있는 광문의 사람됨을 함께 써 보세요.","sampleAnswer":"아이들이 내다 버린 죽은 아이의 주검을 거적에 싸서 등에 지고 가 수표교 아래에 묻어 주고 그 앞에서 울었습니다. 자기를 때리고 내쫓은 사람들을 원망하는 대신 해야 할 일을 하는 사람이며, 자기가 한 일을 남에게 알리려 하지도 않는 사람임을 알 수 있습니다.","keywords":["주검","수표교"]},{"position":1,"type":"short_answer","prompt":"약방에서 돈이 없어졌을 때 광문은 왜 변명하지 않았나요? 그리고 그 결과 어떤 일이 일어났나요?","sampleAnswer":"아니라고 말해 봐야 상대의 마음이 달라지지 않는다고 보았고, 주인의 마음이 편하면 그만이라고 여겼기 때문입니다. 뒤에 처조카가 돈을 가져갔다고 밝히면서 오해가 풀렸고, 주인이 이 일을 사람들에게 알리면서 광문의 이름이 장안에 퍼져 담보 없이도 보증을 설 수 있을 만큼 신용을 얻게 되었습니다.","keywords":["처조카","이름"]},{"position":2,"type":"short_answer","prompt":"박지원은 광문의 외모가 몹시 볼품없다는 것을 첫머리에 자세히 적어 둡니다. 그렇게 한 까닭은 무엇일까요?","sampleAnswer":"겉모습이 뛰어나서 사람들이 좋아한 것이 아님을 분명히 하기 위해서입니다. 볼 데가 하나도 없다고 먼저 못 박아 두었기 때문에, 사람들이 광문을 아낀 까닭이 오직 그 사람됨에 있다는 점이 더 뚜렷하게 드러납니다.","keywords":["겉모습","사람됨"]},{"position":3,"type":"essay","prompt":"광문은 담보도 문서도 없이 보증만으로 사람들의 믿음을 얻었습니다. 오늘날 누군가를 믿을 만한 사람이라고 판단할 때 여러분은 무엇을 보나요? 작품과 연결해 자신의 생각을 써 보세요.","rubric":"재산·지위 같은 조건과 사람됨·행동을 구분해 생각했는지, 그리고 작품 속 근거와 자기 경험을 함께 들어 주장을 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'gwangmun';

-- 허생전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"허생이 칠 년 만에 책을 덮고 집을 나서게 된 계기는 무엇인가요?","sampleAnswer":"사흘을 굶은 아내가 ''장인바치도 못 하고 장사도 못 한다면 어찌 도둑질은 못 하느냐''고 쏘아붙였기 때문입니다. 허생은 십 년을 채우려던 글공부를 칠 년 만에 접고 집을 나섰습니다.","keywords":["아내","도둑질"]},{"position":1,"type":"short_answer","prompt":"허생이 과일을 모조리 사들인 뒤 ''이 나라의 형편을 알 만하구나''라고 탄식한 까닭은 무엇일까요?","sampleAnswer":"단돈 만 냥으로 온 나라의 과일을 사들여 값을 열 배로 올릴 수 있었다는 것은, 조선의 상업 기반과 물자 유통이 그만큼 허약하다는 뜻이기 때문입니다. 허생은 자기 재주를 자랑한 것이 아니라 나라 경제의 취약함을 걱정한 것입니다.","keywords":["과일","경제"]},{"position":2,"type":"short_answer","prompt":"허생이 이완에게 제시한 세 가지 계책은 각각 무엇이며, 이완은 왜 모두 거절했나요?","sampleAnswer":"첫째 임금이 몸소 찾아가 인재를 모실 것, 둘째 명나라 유민에게 종실의 딸을 시집보내고 권세가의 재산을 나누어 줄 것, 셋째 자제들의 머리를 깎고 청나라 옷을 입혀 정탐하게 할 것입니다. 이완은 사대부의 체면과 예법을 이유로 모두 어렵다고 했습니다.","keywords":["이완","체면"]},{"position":3,"type":"essay","prompt":"허생은 ''이른바 사대부라는 것들이 대체 무엇이냐''며 크게 화를 냅니다. 말로는 큰소리치면서 정작 작은 것도 바꾸지 못하는 모습을 오늘날에도 본 적이 있나요? 자신의 생각을 써 보세요.","rubric":"명분과 실천의 괴리라는 주제를 이해했는지, 그리고 그것을 오늘의 사례나 경험과 연결해 자기 생각을 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'heosaeng';

-- 흥부전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"놀부의 성격이 매우 괴팍하고 심술궂다는 것을 설명하기 위해 본문에서 사용한 비유적 표현(신체 부위 관련)은 무엇인가요?","sampleAnswer":"심술보. 사람들은 놀부가 오장육부 외에 ''심술보''라는 장기를 하나 더 달고 태어났다고 말했습니다.","keywords":["심술보"]},{"position":1,"type":"short_answer","prompt":"흥부가 가족을 먹여 살리기 위해 관청에 가서 대신 매를 맞고 돈을 벌기로 한 일을 무엇이라고 부르며, 그 결과는 어떠했나요?","sampleAnswer":"매품팔이라고 합니다. 그러나 나라에 경사가 있어 죄인들이 모두 풀려나는 바람에 매를 맞지 못했고, 흥부는 돈 한 푼 없이 빈손으로 돌아왔습니다.","keywords":["매품","경사"]},{"position":2,"type":"short_answer","prompt":"흥부의 박씨와 놀부의 박씨에 적혀 있던 글자는 각각 무엇이며, 그 의미는 어떻게 다른가요?","sampleAnswer":"흥부의 박씨에는 ''보은표(報恩瓢)'' 곧 은혜를 갚는 박이라고 적혀 있었고, 놀부의 박씨에는 ''보수표(報讐瓢)'' 곧 원수를 갚는 박이라고 적혀 있었습니다. 같은 제비가 물어다 준 박씨였지만 어떤 마음으로 제비를 대했는가에 따라 은혜와 응징으로 결과가 갈린 것입니다.","keywords":["보은표","보수표"]},{"position":3,"type":"essay","prompt":"흥부는 자신을 내쫓고 괴롭혔던 형 놀부를 결국 용서하고 재산까지 나누어 줍니다. 여러분이 흥부였다면 어떻게 했을 것 같나요? 그렇게 생각한 까닭과 함께 써 보세요.","rubric":"용서 여부에 정답은 없습니다. 자신의 선택을 밝히고, 그 까닭을 작품 속 상황이나 자신의 경험과 연결해 설명했는지를 봅니다."}]'::jsonb
  WHERE slug = 'heungbu';

-- 호질
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"북곽 선생과 동리자는 세상에서 어떤 사람으로 알려져 있었나요? 그리고 실제 모습은 어떠했나요?","sampleAnswer":"북곽 선생은 만 권의 책을 펴내 천자와 제후까지 우러르던 이름난 학자였고, 동리자는 절개를 지킨 과부로 나라에서 정문을 세워 표창한 인물이었습니다. 그러나 실제로는 북곽 선생이 한밤중에 동리자의 방에 있었고, 동리자에게는 성이 저마다 다른 아들이 다섯 있었습니다.","keywords":["북곽 선생","동리자"]},{"position":1,"type":"short_answer","prompt":"범은 사람이 짐승보다 잔인하다고 말하며 어떤 근거를 들었나요? 두 가지 이상 써 보세요.","sampleAnswer":"범은 배가 고파야 사냥하고 배부르면 그치지만 사람은 배불러도 이익을 다투며 서로를 죽인다는 점, 메뚜기와 누에와 벌에게서 먹을 것과 입을 것을 빼앗는다는 점, 그리고 전쟁을 일으켜 하루아침에 수많은 사람을 죽인다는 점을 들었습니다.","keywords":["전쟁","이익"]},{"position":2,"type":"short_answer","prompt":"범이 떠난 뒤 북곽 선생은 농부를 만나자 어떻게 행동했나요? 그 결말이 주는 느낌을 함께 써 보세요.","sampleAnswer":"곧바로 옷매무새를 가다듬고 하늘과 땅을 논하는 점잖은 말을 지어내며 다시 어진 선비 행세를 했습니다. 위선이 낱낱이 드러났는데도 조금도 뉘우치지 않는 모습에서, 이런 사람은 들켜도 바뀌지 않는다는 서늘함이 느껴집니다.","keywords":["선비","뉘우"]},{"position":3,"type":"essay","prompt":"이 작품에서 사람을 꾸짖는 것은 사람이 아니라 범입니다. 작가는 왜 짐승의 입을 빌렸을까요? 그리고 겉모습과 실제가 다른 경우를 본 적이 있다면 함께 써 보세요.","rubric":"짐승을 내세워 사람을 비판하는 우화의 방식과 그 효과를 이해했는지, 그리고 작품의 문제의식을 자기 경험이나 오늘의 사례와 연결했는지를 봅니다."}]'::jsonb
  WHERE slug = 'hojil';

-- 홍길동전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"길동이 달밤에 검을 들고 탄식하며 한 말은 무엇이며, 그가 괴로워한 까닭은 무엇인가요?","sampleAnswer":"''아버지를 아버지라 부르지 못하고 형을 형이라 부르지 못한다''며 탄식했습니다. 첩의 몸에서 태어난 서자였기 때문에 아버지와 형을 제대로 부를 수 없었고 벼슬길에도 나아갈 수 없었기 때문입니다.","keywords":["아버지","서자"]},{"position":1,"type":"short_answer","prompt":"길동이 만든 무리의 이름은 무엇이며, 그들이 지킨 원칙은 무엇이었나요?","sampleAnswer":"활빈당(活貧黨), 곧 가난한 사람을 살리는 무리입니다. 백성의 재물은 건드리지 않고, 백성을 쥐어짜 재물을 모은 벼슬아치와 부정하게 재물을 쌓은 자들의 것만 빼앗아 굶주린 백성에게 나누어 주었습니다.","keywords":["활빈당","백성"]},{"position":2,"type":"short_answer","prompt":"길동이 임금에게 재물이나 다른 벼슬이 아니라 굳이 ''병조판서''를 달라고 한 까닭은 무엇일까요?","sampleAnswer":"병조판서는 나라의 군사를 총괄하는 높은 벼슬로, 서자에게는 애초에 허락되지 않는 자리였습니다. 길동은 그 자리를 받음으로써 신분 때문에 막혔던 길이 부당했음을 세상에 드러내고, 평생의 한을 푸는 것을 원했던 것입니다.","keywords":["병조판서","서자"]},{"position":3,"type":"essay","prompt":"길동은 결국 조선을 떠나 바다 건너에 새 나라를 세웁니다. 왜 조선 안에서는 자신이 바라던 세상을 만들 수 없었을까요? 그리고 오늘날 우리 사회에도 ''태어난 조건 때문에 기회가 막히는 일''이 있다고 생각하는지 자신의 생각을 써 보세요.","rubric":"작품 속 신분 제도의 문제를 이해했는지, 그리고 그것을 오늘의 현실과 연결해 자기 생각을 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'honggildong';

-- 홍계월전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"계월이 남자 옷을 입고 자라게 된 경위를 쓰고, 그 남장이 결과적으로 계월에게 어떤 길을 열어 주었는지 함께 써 보세요.","sampleAnswer":"지나가던 도사가 다섯 살에 큰 액운이 있으니 남자 옷을 입혀 기르라고 일러 주었고 부모가 그 말을 따랐습니다. 그 덕분에 계월은 보국과 함께 글과 무예를 배우고 과거를 보아 장원으로 급제한 뒤 벼슬에 올라 대원수가 될 수 있었습니다. 여자로서는 열리지 않았을 길이 남장을 통해 열린 것입니다.","keywords":["도사","대원수"]},{"position":1,"type":"short_answer","prompt":"계월이 여자임이 밝혀졌을 때 임금은 어떻게 했나요? 그 판단이 왜 중요한지 함께 설명해 보세요.","sampleAnswer":"임금은 ''짐이 맡긴 것은 나라의 군사였지 남자의 몸이 아니었다''며 벼슬을 그대로 두고 오히려 더 높은 자리를 내렸습니다. 남장 이야기는 대개 정체가 드러나면 여성이 집으로 돌아가며 끝나는데, 이 작품은 능력으로 얻은 자리가 성별이 밝혀졌다고 사라지지 않는다고 말한다는 점에서 중요합니다.","keywords":["임금","벼슬"]},{"position":2,"type":"short_answer","prompt":"혼인한 뒤 계월과 보국 사이에 갈등이 생긴 근본 원인은 무엇이며, 그 갈등은 어떻게 풀렸나요?","sampleAnswer":"집에서는 부부이지만 조정에서는 계월이 보국의 윗사람이라는 어긋남 때문입니다. 남편이 위여야 한다는 당시의 규범과 능력에 따라 정해진 실제 지위가 부딪힌 것입니다. 뒷날 전장에서 위기에 빠진 보국을 계월이 구해 내고, 보국이 자신이 다투던 것이 무엇이었는지 깨달으면서 두 사람이 서로를 존중하게 되었습니다.","keywords":["부부","보국"]},{"position":3,"type":"essay","prompt":"이 작품은 여성이 대원수가 되는 이야기이면서, 동시에 남장을 해야만 그것이 가능했던 이야기이기도 합니다. 이백 년 전 사람들이 이런 소설을 지어 읽은 까닭은 무엇일까요? 자신의 생각을 써 보세요.","rubric":"작품이 넘어선 것과 넘어서지 못한 것을 함께 보았는지, 그리고 당시 독자(특히 여성 독자)의 처지와 연결해 자기 생각을 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'honggyewol';

-- 화용도
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"''군사설움타령''은 어떤 대목이며, 원작 「삼국지연의」와 견줄 때 어떤 의미가 있나요?","sampleAnswer":"싸움 전날 밤 군막에서 군사들이 저마다 두고 온 늙은 어머니와 처자, 논밭을 이야기하며 신세를 한탄하는 대목입니다. 원작에는 없고 우리 판소리가 새로 지어 넣은 것으로, 전쟁을 지휘하는 영웅이 아니라 끌려온 사람들의 눈으로 사건을 다시 보게 만듭니다.","keywords":["군사","어머니"]},{"position":1,"type":"short_answer","prompt":"달아나던 조조가 세 번 웃을 때마다 무슨 일이 일어났나요? 그리고 이런 반복이 만들어 내는 효과는 무엇인가요?","sampleAnswer":"웃을 때마다 복병이 나타났습니다. 첫 번째는 조자룡, 두 번째는 장비, 세 번째는 관우였습니다. 같은 일이 세 번 되풀이되면서 조조의 자만이 매번 무너지고, 원작에서 두렵던 인물이 우스운 인물로 바뀝니다.","keywords":["복병","조조"]},{"position":2,"type":"short_answer","prompt":"이 작품이 전쟁을 다루는 방식은 「유충렬전」이나 「박씨전」과 어떻게 다른가요?","sampleAnswer":"유충렬전과 박씨전은 뛰어난 영웅을 내세워 적을 물리치게 함으로써 현실에서 겪은 패배를 이야기 속에서 되갚습니다. 반면 화용도에는 그런 통쾌한 승리가 없고, 대신 이름 없이 죽어 간 군사들의 설움과 그 넋을 불러내어 전쟁의 참상 자체를 드러냅니다.","keywords":["유충렬전","군사"]},{"position":3,"type":"essay","prompt":"한 군사가 ''승상은 천하를 얻으려 하시지만 우리가 얻을 것은 무엇이오?''라고 묻습니다. 이 물음이 오늘날에도 유효하다고 생각하나요? 자신의 생각을 써 보세요.","rubric":"전쟁의 이익과 대가가 서로 다른 사람에게 돌아간다는 문제의식을 파악했는지, 그리고 그것을 오늘의 사례나 자기 생각과 연결해 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'hwayongdo';

-- 이춘풍전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"이춘풍이 재산을 잃은 뒤 김씨는 무엇을 했나요? 그리고 남편에게서 무엇을 받아 두었나요?","sampleAnswer":"삯바느질과 남의 집 빨래, 길쌈을 하며 새벽부터 밤까지 일해 잡혔던 집을 도로 찾고 팔았던 논밭까지 조금씩 되사들였습니다. 그리고 남편이 잘못을 뉘우치자 말로만 하지 말라며 다시는 방탕하지 않겠다는 다짐을 글로 써서 받아 궤에 넣어 두었습니다.","keywords":["삯바느질","다짐"]},{"position":1,"type":"short_answer","prompt":"김씨는 평양으로 떠나려는 남편을 어떻게 만류했으며, 이춘풍은 무엇이라 답했나요?","sampleAnswer":"평양은 색향이라는 점과, 호조에서 빌린 돈은 나랏돈이라 잃으면 옥에 간다는 점을 들어 말렸고, 예전에 받아 둔 다짐 글까지 꺼내 보였습니다. 그러나 이춘풍은 ''아녀자가 사내 일에 나서는 것이 아니오''라며 물리치고 돈을 지고 떠났습니다.","keywords":["나랏돈","아녀자"]},{"position":2,"type":"short_answer","prompt":"남편을 찾기 위해 김씨가 한 일을 순서대로 정리해 보세요.","sampleAnswer":"소식이 끊기자 사람을 놓아 사정을 알아본 뒤, 평안 감사로 부임하는 이웃에게 청을 넣어 비장 자리를 얻고 남장을 하고 평양으로 갔습니다. 그곳에서 기생 추월을 잡아들여 장부와 증인을 들이대 돈 이천 냥을 되찾았고, 남의 집 심부름꾼이 되어 있던 남편을 끌어내 꾸짖고 매를 쳐 벌한 뒤 돈을 주어 서울로 돌려보냈습니다.","keywords":["비장","추월"]},{"position":3,"type":"essay","prompt":"김씨는 남자 옷을 입어야만 남편을 찾고 돈을 되찾을 수 있었습니다. 능력이 부족해서가 아니라 자격이 주어지지 않았기 때문입니다. 「홍계월전」의 계월도 같았습니다. 이런 설정이 오늘 우리에게 무엇을 생각하게 하는지 자신의 생각을 써 보세요.","rubric":"남장이 능력의 문제가 아니라 제도와 자격의 문제였음을 파악했는지, 두 작품을 연결해 생각했는지, 그리고 오늘의 현실이나 자기 경험과 이어 자기 생각을 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'ichunpung';

-- 임경업전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"임경업은 백마산성을 끝까지 지켜 냈는데도 나라는 무너졌습니다. 어떻게 그런 일이 일어났나요?","sampleAnswer":"청군이 여러 번 백마산성을 쳤으나 뚫지 못하자, 그 성을 아예 우회해 곧장 한양으로 내려갔기 때문입니다. 임경업은 군사가 적어 대군을 뒤쫓아 막을 수 없었고, 결국 도성이 함락되고 임금이 항복하는 것을 성 위에서 지켜보아야 했습니다.","keywords":["백마산성","한양"]},{"position":1,"type":"short_answer","prompt":"청나라가 명나라를 치라며 군사를 요구했을 때 임경업은 어떤 곤란한 처지에 놓였고, 어떻게 행동했나요?","sampleAnswer":"거절하면 나라가 위태롭고, 따르면 은혜를 입은 명나라를 저버리는 처지였습니다. 임경업은 명나라 진영에 미리 사람을 보내 사정을 알리고, 화살촉을 뺀 화살을 쏘고 북만 울리며 싸우는 척만 하다 물러나는 방식으로 두 가지를 모두 지키려 했습니다.","keywords":["명나라","은혜"]},{"position":2,"type":"short_answer","prompt":"임경업은 적국의 황제에게는 목숨을 구했지만 결국 조선에서 죽습니다. 이 결말이 무엇을 말한다고 생각하나요?","sampleAnswer":"적국의 황제조차 그 충의를 인정해 놓아주었는데, 정작 같은 나라의 권신 김자점이 모함해 죽였습니다. 나라를 위태롭게 하는 것이 바깥의 적만이 아니라 안의 문제이기도 하다는 것, 그리고 옳게 산 사람이 반드시 보상받지는 않는다는 현실을 함께 보여 줍니다.","keywords":["김자점","황제"]},{"position":3,"type":"essay","prompt":"「유충렬전」의 주인공은 나타나 적을 무찌르고 모든 것을 되찾지만, 임경업은 끝내 이기지 못합니다. 그런데도 이 이야기가 널리 읽힌 까닭은 무엇일까요? 두 작품을 견주어 자신의 생각을 써 보세요.","rubric":"임경업이 실존 인물이어서 결말을 바꿀 수 없었다는 점을 파악했는지, 그럼에도 작품이 무엇을 전하려 했는지 짚었는지, 그리고 두 작품을 견주어 자기 생각을 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'imgyeongeop';

-- 이생규장전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"이생과 최랑은 어떻게 서로를 알게 되었나요? 두 사람이 마음을 나눈 방법의 특징을 함께 써 보세요.","sampleAnswer":"이생이 국학에 오가다 담 안에서 들려온 최랑의 시를 듣고 마음이 움직여, 시를 적어 담 안으로 던져 넣으면서 시작되었습니다. 두 사람은 얼굴보다 먼저 글로 서로를 알아보았고, 만난 뒤에도 밤마다 시를 주고받으며 재주로 마음을 나누었습니다.","keywords":["담","시"]},{"position":1,"type":"short_answer","prompt":"홍건적의 난에서 최랑은 어떻게 최후를 맞았나요? 그 장면에서 드러나는 최랑의 성격을 함께 써 보세요.","sampleAnswer":"도적에게 붙들려 협박을 받았지만 굽히지 않고 크게 꾸짖다가 목숨을 잃었습니다. 담 너머로 먼저 답장을 보내고 사다리를 내려 준 일에서도 알 수 있듯, 최랑은 스스로 판단하고 그 뜻을 끝까지 지키는 인물입니다.","keywords":["도적","꾸짖"]},{"position":2,"type":"short_answer","prompt":"죽은 최랑이 돌아왔을 때 이생은 놀라지 않고 받아들입니다. 그리고 몇 해 뒤 최랑은 기한이 다해 다시 떠납니다. 작가는 왜 두 사람을 다시 만나게 했다가 또 헤어지게 했을까요?","sampleAnswer":"다시 만나게 함으로써 죽음으로도 끊어지지 않는 마음을 보여 주고, 다시 헤어지게 함으로써 사람의 힘으로는 어쩔 수 없는 한계를 보여 줍니다. 만남과 이별을 두 번 겪게 하여 인연의 소중함과 삶의 덧없음을 함께 드러낸 것입니다.","keywords":["만남","이별"]},{"position":3,"type":"essay","prompt":"이 작품은 우리나라 최초의 소설집에 실린 작품입니다. 600년 가까이 지난 지금 읽어도 마음에 남는 부분이 있었나요? 어느 장면이었는지, 왜 그랬는지 써 보세요.","rubric":"특정한 정답은 없습니다. 인상 깊은 장면을 구체적으로 고르고, 그 까닭을 작품 속 상황이나 자신의 경험과 연결해 설명했는지를 봅니다."}]'::jsonb
  WHERE slug = 'isaeng';

-- 장끼전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"까투리는 콩을 먹지 말라며 어떤 근거를 들었나요? 꿈 이야기 말고 다른 근거도 함께 써 보세요.","sampleAnswer":"간밤에 꾼 네 가지 흉몽을 이야기했고, 그와 함께 눈 위에 사람 발자국이 어지럽고 콩 둘레만 눈이 다져져 있으니 누군가 일부러 놓아둔 것이라는 점을 짚었습니다. 미신에 기댄 말이 아니라 직접 살펴본 근거가 있는 말이었습니다.","keywords":["발자국","콩"]},{"position":1,"type":"short_answer","prompt":"장끼는 까투리의 말을 어떤 방식으로 물리쳤나요? 그 태도의 문제점을 함께 써 보세요.","sampleAnswer":"흉몽을 모두 좋은 징조라고 제멋대로 뒤집어 풀이하고, ''계집이 무슨 말이 그리 많으냐''며 말한 사람의 성별을 문제 삼았습니다. 말의 옳고 그름을 따지는 대신 누가 말했는지를 문제 삼았다는 점이 잘못이며, 그 결과 목숨을 잃고 스물한 마리 새끼가 아버지를 잃게 됩니다.","keywords":["계집","흉몽"]},{"position":2,"type":"short_answer","prompt":"장끼의 유언에는 무엇이 담겨 있고, 반대로 무엇이 빠져 있나요?","sampleAnswer":"아내에게 개가하지 말고 수절하라는 요구가 담겨 있습니다. 반면 남은 스물한 마리 새끼를 어떻게 먹이고 기를 것인지, 겨울을 어떻게 날 것인지, 자기 고집으로 이렇게 되어 미안하다는 말은 빠져 있습니다. 죽는 순간까지 자기 체면을 앞세운 것입니다.","keywords":["수절","새끼"]},{"position":3,"type":"essay","prompt":"이 작품은 까투리가 재혼하는 것으로 끝나며, 그것을 부끄러운 일로 그리지 않습니다. 재가한 여성의 자손이 벼슬길에서 배제되던 시대에 이런 결말이 어떤 의미였을지, 그리고 여러분은 까투리의 선택을 어떻게 보는지 써 보세요.","rubric":"당시의 재가 금지 제도를 이해했는지, 결말이 그 제도에 대해 어떤 태도를 취하는지 파악했는지, 그리고 자기 생각을 근거와 함께 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'janggi';

-- 장화홍련전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"계모 허씨가 장화를 모함하기 위해 사용한 물건은 무엇이며, 나중에 그 진상은 어떻게 밝혀졌나요?","sampleAnswer":"껍질을 벗겨 피를 묻힌 죽은 쥐를 장화의 이불 속에 몰래 넣어 두고 몹쓸 짓을 저질렀다고 모함했습니다. 나중에 정 부사가 그 증거를 자세히 살펴보니 사람의 몸에서 나온 것이 아니라 껍질 벗긴 죽은 쥐임이 드러났습니다.","keywords":["쥐","이불"]},{"position":1,"type":"short_answer","prompt":"아버지 배 좌수는 어떤 잘못을 저질렀나요? 그의 잘못을 계모의 잘못과 비교해 설명해 보세요.","sampleAnswer":"어두운 새벽이라 제대로 살펴보지도 않고 아내의 말만 곧이들었으며, 집안의 체면이 상할까 두려워 제 딸을 죽음으로 내몰았습니다. 계모가 악의로 모함했다면, 아버지는 사실을 확인하지 않고 체면만 앞세운 어리석음과 무책임으로 딸을 잃게 했습니다.","keywords":["체면","계모"]},{"position":2,"type":"short_answer","prompt":"장화와 홍련은 왜 살아 있을 때가 아니라 죽어서 원귀가 된 뒤에야 억울함을 말할 수 있었을까요?","sampleAnswer":"당시 여성은 스스로 억울함을 밝히고 항변할 기회를 얻기 어려웠기 때문입니다. 장화는 변명할 틈도 없이 끌려갔고, 자매의 말을 들어 줄 어른도 없었습니다. 그래서 죽은 뒤 부사에게 나타나서야 비로소 사연을 전할 수 있었습니다.","keywords":["여성","억울"]},{"position":3,"type":"essay","prompt":"배 좌수는 확인 한 번만 했어도 진실을 알 수 있었지만 그러지 않았습니다. 한쪽 이야기만 듣고 판단해서 오해가 생긴 일을 겪거나 본 적이 있나요? 그런 일을 막으려면 무엇이 필요할지 써 보세요.","rubric":"사실 확인의 중요성이라는 주제를 이해했는지, 자기 경험이나 주변 사례와 연결해 생각을 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'janghwa';

-- 전우치전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"황금 들보 사건의 전개를 정리하고, 이 방법이 왜 통쾌하게 읽히는지 설명해 보세요.","sampleAnswer":"전우치가 선관으로 둔갑해 대궐 하늘에 나타나 옥황상제의 명이라며 황금 들보를 바치라 합니다. 조정은 온 나라의 금을 거두어 들보를 만들어 바치고, 전우치는 그것을 팔아 곡식을 사서 굶주린 마을에 나눠 줍니다. 담을 넘어 훔친 것이 아니라 그들이 믿는 하늘의 권위를 이용해 스스로 내놓게 만들었다는 점, 그리고 그 금이 흉년에 곳간을 잠그고 있던 대신과 부자들에게서 나왔다는 점 때문에 통쾌하게 읽힙니다.","keywords":["옥황상제","곡식"]},{"position":1,"type":"short_answer","prompt":"전우치와 홍길동을 출발점·활동 방식·결말의 세 가지 면에서 견주어 보세요.","sampleAnswer":"출발점에서 홍길동은 서자로서 아버지를 아버지라 부르지 못하는 개인의 한에서 시작하지만, 전우치에게는 그런 사연이 없고 굶어 죽는 사람을 본 것이 계기입니다. 활동 방식에서 홍길동은 활빈당이라는 조직을 만들지만 전우치는 끝까지 혼자 다닙니다. 결말에서 홍길동은 율도국을 세워 임금이 되지만 전우치는 산으로 들어가 자취를 감춥니다.","keywords":["활빈당","율도국"]},{"position":2,"type":"short_answer","prompt":"서화담은 ''네가 곡식을 나눠 준 그 마을은 이듬해에 또 굶는다''고 말합니다. 이 지적이 옳다고 생각하나요? 그렇다면 전우치가 한 일은 무의미한가요?","sampleAnswer":"지적 자체는 옳습니다. 전우치가 한 일은 그때그때의 응급 처치였고 굶주림의 원인을 없애지는 못했습니다. 그러나 무의미하다고 보기는 어렵습니다. 그가 거둔 금은 흉년에 곳간을 잠그고 있던 자들에게서 나온 것이라 방향으로 보면 되돌려 놓기에 가깝고, 당장 굶던 사람들에게는 실제로 밥이 되었기 때문입니다. 오래가지 못했다는 것과 옳지 않았다는 것은 다릅니다.","keywords":["곳간","굶"]},{"position":3,"type":"essay","prompt":"전우치는 잡히지도 죽지도 않고 산으로 들어가 사라집니다. 이런 결말이 당시 사람들에게 어떤 의미였을지 자신의 생각을 써 보세요.","rubric":"결말이 열려 있다는 점을 파악했는지, 그리고 그것이 당시 독자에게 갖는 의미를 자기 나름대로 해석했는지를 봅니다. 정해진 답은 없습니다."}]'::jsonb
  WHERE slug = 'jeonuchi';

-- 조웅전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"이 작품의 사건을 ''조웅이 힘을 잃는 과정 → 힘을 기르는 과정 → 힘을 쓰는 과정''으로 나누어 정리해 보세요.","sampleAnswer":"힘을 잃는 과정은 아버지 조정인이 이두병의 참소로 죽고, 이두병이 태자를 내쫓고 임금이 되며, 벽서 사건으로 조웅 모자가 도망치는 데까지입니다. 힘을 기르는 과정은 강선암에서 글을 읽고 화산에서 철관 도사에게 삼 년간 병법과 무예를 익히며 삼척검과 명마를 얻는 대목입니다. 힘을 쓰는 과정은 위국을 도와 서번을 물리치고, 태자를 모셔 온 뒤 이두병을 처단해 나라를 되돌리는 대목입니다.","keywords":["이두병","철관 도사"]},{"position":1,"type":"short_answer","prompt":"조웅이 이두병을 치기 전에 먼저 태자를 모셔 온 것은 왜 중요한가요?","sampleAnswer":"조웅이 스스로 임금이 되려는 것이 아니라 원래 주인에게 자리를 돌려주려는 것임을 분명히 하기 때문입니다. 이 순서 덕분에 조웅의 행동이 개인의 복수를 넘어 잘못된 것을 바로잡는 일이 되고, 이두병의 찬탈과도 뚜렷이 구별됩니다.","keywords":["임금","이두병"]},{"position":2,"type":"short_answer","prompt":"「유충렬전」과 이 작품은 뼈대가 비슷하지만 주인공이 힘을 얻는 방식이 다릅니다. 어떻게 다른지 설명해 보세요.","sampleAnswer":"유충렬은 도승에게 갑옷과 보검을 받고 위기마다 하늘이 도와주는, 태어날 때부터 정해진 영웅에 가깝습니다. 반면 조웅은 화산에서 철관 도사에게 삼 년 동안 병법과 무예를 배워 강해집니다. 초월적 조력보다 스스로 쌓은 실력이 앞선다는 점에서 노력으로 만들어진 영웅에 가깝습니다.","keywords":["유충렬","도사"]},{"position":3,"type":"essay","prompt":"일곱 살 조웅은 아무런 힘도 없을 때 담벼락에 이두병을 비판하는 글을 썼습니다. 어른들은 알면서도 침묵했지요. 이 장면이 오늘 우리에게 던지는 물음은 무엇이라고 생각하나요?","rubric":"힘없는 사람이 먼저 말했다는 점, 다수의 침묵과 대비된다는 점을 읽어 냈는지 봅니다. 그것을 자기 경험이나 오늘의 사례와 연결해 자기 생각을 세웠으면 충분합니다. 정해진 답은 없습니다."}]'::jsonb
  WHERE slug = 'joung';

-- 만복사저포기
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"양생은 어떤 처지의 사람이었으며, 부처와 어떤 내기를 걸었나요?","sampleAnswer":"일찍 부모를 여의고 장가도 들지 못한 채 만복사 방 한 칸을 빌려 홀로 지내던 외로운 젊은이였습니다. 삼월 스무나흗날 밤 법당에서 저포를 던져, 자기가 지면 법회를 열어 갚고 부처가 지면 아름다운 배필을 달라는 내기를 걸었고 이겼습니다.","keywords":["저포","배필"]},{"position":1,"type":"short_answer","prompt":"여인이 부처 앞에서 읽은 축원문에는 어떤 사연이 담겨 있었나요? 그 사연이 당시 현실과 어떻게 이어지는지 함께 써 보세요.","sampleAnswer":"왜적이 쳐들어왔을 때 몸을 지키려다 목숨을 잃고 들판에 버려졌으며, 부모가 거두어 주었으나 짝 없이 홀로 지낸 지 삼 년이 되었다는 내용입니다. 고려 말 왜구의 침입이 잦던 시기에 실제로 수많은 사람이 이렇게 목숨을 잃고 제대로 묻히지도 못했으므로, 한 사람의 사연이면서 그 시대의 사연이기도 합니다.","keywords":["왜적","목숨"]},{"position":2,"type":"short_answer","prompt":"여인이 준 은그릇은 이야기에서 어떤 구실을 하나요?","sampleAnswer":"여인의 무덤에 함께 묻었던 물건이어서, 보련사로 가던 부모가 그것을 알아보고 양생을 붙들게 됩니다. 그 덕분에 양생이 겪은 기이한 사흘이 사실로 인정받고, 여인의 정체와 사연이 밝혀지며, 양생이 사위로 받아들여지게 됩니다.","keywords":["무덤","부모"]},{"position":3,"type":"essay","prompt":"이 작품과 같은 책에 실린 「이생규장전」은 둘 다 산 사람과 죽은 사람이 만났다가 정해진 기한이 다해 헤어지고, 남은 사람도 오래지 않아 세상을 떠납니다. 김시습은 왜 이런 이야기를 되풀이해 썼을까요? 작가의 삶과 연결해 자신의 생각을 써 보세요.","rubric":"두 작품의 공통 구조를 파악했는지, 김시습이 벼슬을 마다하고 평생 떠돈 인물이라는 사실과 연결해 해석했는지, 그리고 자기 생각을 근거와 함께 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'manboksa';

-- 남염부주지
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"박생은 어떤 생각을 가진 사람이었나요? 그가 지은 글의 제목과 내용을 함께 써 보세요.","sampleAnswer":"귀신이나 지옥, 부처에게 빌면 복을 받는다는 이야기를 믿지 않는 유학자였습니다. 천지에는 오직 하나의 이치가 있을 뿐이라고 여겨 「일리론(一理論)」이라는 글을 지었고, 귀신이나 지옥 같은 것은 그 이치를 벗어난 헛된 말이라고 주장했습니다.","keywords":["일리론","이치"]},{"position":1,"type":"short_answer","prompt":"염왕은 ''재물을 바치면 죄가 없어진다''는 생각을 어떻게 반박했나요?","sampleAnswer":"부처의 본래 가르침은 마음을 밝히고 욕심을 덜라는 것이어서 나쁠 것이 없으나, 뒷사람들이 그것을 재물 거래로 바꾸어 놓았다고 지적했습니다. 재물로 죄를 벗을 수 있다면 가난한 사람은 벗어날 길이 없으니, 그런 이치는 세상에 있을 수 없다는 것입니다.","keywords":["재물","가난"]},{"position":2,"type":"short_answer","prompt":"이 작품은 앞의 세 편과 짜임이 크게 다릅니다. 어떤 점이 다른지, 그리고 염왕이 박생의 생각을 꺾지 않고 인정해 주는 것을 어떻게 볼 수 있을지 써 보세요.","sampleAnswer":"앞의 세 편은 남녀의 만남과 이별을 다루지만 이 작품에는 사랑도 이별도 없고 처음부터 끝까지 사상 토론으로 이루어져 있습니다. 또 염왕이 박생의 생각을 하나하나 옳다고 인정해 주므로, 염왕을 박생 자신의 생각이 밖으로 드러난 존재로 볼 수 있습니다. 세상에서 아무도 들어 주지 않던 생각을 꿈속에서 확인받는 셈입니다.","keywords":["토론","염왕"]},{"position":3,"type":"essay","prompt":"염왕은 ''임금이 임금 노릇을 못 하면 그 자리는 이미 임금의 자리가 아니다''라고 말합니다. 김시습이 이런 말을 왜 저승 임금의 입을 빌려, 그것도 꿈속의 일로 만들어 썼을지 자신의 생각을 써 보세요.","rubric":"수양대군의 왕위 찬탈이라는 배경과 연결해 이해했는지, 하기 어려운 말을 우회해서 하는 방식(꿈·다른 존재의 입)을 파악했는지, 그리고 자기 생각을 근거와 함께 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'namyeombuju';

-- 옹고집전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"옹고집은 어떤 사람이었나요? 재물, 이웃, 어머니에 대한 태도를 각각 들어 써 보세요.","sampleAnswer":"논이 백 마지기가 되는 부자였으나 몹시 인색했습니다. 품삯을 깎고, 흉년에 곡식을 꾸러 온 이웃에게 문을 닫아걸었으며, 걸인이 오면 개를 풀어 쫓았습니다. 여든 넘은 어머니는 뒤채 냉방에 두고 나무도 넉넉히 때 드리지 않았으며, 병이 들어도 약을 쓰지 않았습니다.","keywords":["인색","어머니"]},{"position":1,"type":"short_answer","prompt":"관가에서 사또는 무엇을 근거로 가짜를 진짜라고 판단했나요? 그 판결 방식에 어떤 문제가 있는지 함께 써 보세요.","sampleAnswer":"집안의 재물 내역, 곧 쌀이 몇 섬이고 누구에게 얼마를 빌려주었는지를 더 자세히 아는 쪽을 진짜로 보았습니다. 사람을 그 사람 자체가 아니라 가진 재물에 대한 정보로 확인한 셈이어서, 재물이 곧 그 사람이라는 잘못된 기준이 됩니다.","keywords":["재물","진짜"]},{"position":2,"type":"short_answer","prompt":"쫓겨나 떠돌던 옹고집이 크게 뉘우치게 된 계기는 무엇이었나요?","sampleAnswer":"남의 집 문 앞에서 밥을 얻으려다 쫓기고, 개에게 쫓기고, 찬바람 부는 처마 밑에서 웅크리고 자면서 자신이 남에게 했던 일을 그대로 겪었기 때문입니다. 특히 추운 곳에서 자다가 냉방에 두었던 어머니를 떠올린 것이 결정적이었습니다.","keywords":["어머니","쫓"]},{"position":3,"type":"essay","prompt":"짚으로 만든 가짜 옹고집이 진짜보다 집안을 더 잘 다스렸다는 설정이 나옵니다. 그렇다면 무엇이 한 사람을 그 사람이게 만드는 것일까요? 자신의 생각을 써 보세요.","rubric":"얼굴이나 재산 같은 겉조건이 아니라 행동과 관계가 사람됨을 이룬다는 작품의 문제의식을 이해했는지, 그리고 자기 생각을 근거와 함께 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'onggojip';

-- 사씨남정기
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"사씨는 왜 스스로 남편에게 첩을 들이라고 청했나요? 그리고 그 결과 어떤 일이 벌어졌나요?","sampleAnswer":"혼인한 지 아홉 해가 되도록 자식이 없어 집안의 대가 끊길까 걱정했기 때문입니다. 그러나 첩으로 들어온 교씨가 아들을 낳은 뒤 안주인 자리를 넘보게 되었고, 동청과 짜고 사씨를 모함하여 집에서 쫓아내는 결과로 이어졌습니다.","keywords":["자식","교씨"]},{"position":1,"type":"short_answer","prompt":"유연수가 아내를 의심하게 된 ''증거''는 무엇이었으며, 그것은 어떻게 만들어진 것이었나요?","sampleAnswer":"사씨가 다른 사내에게 보낸 것처럼 꾸며진 편지였습니다. 동청이 사씨의 옛 글씨를 구해 그 필체를 흉내 내어 만든 가짜 편지를, 교씨와 짜고 유연수가 볼 만한 곳에 흘려 둔 것이었습니다.","keywords":["편지","동청"]},{"position":2,"type":"short_answer","prompt":"이 작품은 겉으로는 중국 명나라 어느 집안의 이야기이지만, 실제로는 당시 조선의 일을 빗댄 것이라고 합니다. 무슨 일을 가리키며, 작가는 왜 그렇게 돌려서 썼을까요?","sampleAnswer":"숙종이 인현왕후를 폐하고 장희빈을 왕비로 세운 일을 빗댄 것입니다. 임금을 정면으로 비판하면 목숨이 위태로웠기 때문에 무대를 중국으로 옮기고 인물의 이름을 바꾸어 이야기 형식으로 썼습니다.","keywords":["인현왕후","장희빈"]},{"position":3,"type":"essay","prompt":"유연수는 ''내 눈으로 보고도 믿지 않는다면 무엇을 믿겠는가''라며 가짜 편지를 믿었습니다. 눈으로 본 것이 늘 사실일까요? 요즘에도 이런 일이 있는지 자신의 생각을 써 보세요.","rubric":"''증거처럼 보이는 것''이 만들어질 수 있다는 작품의 문제의식을 이해했는지, 그리고 그것을 오늘의 사례(가짜 사진·영상, 잘못된 소문 등)와 연결해 생각을 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'sassi';

-- 심청전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"심 봉사가 몽운사 화주승에게 덜컥 약속해 버린 것은 무엇이며, 그 약속을 한 뒤 왜 후회했나요?","sampleAnswer":"공양미 삼백 석을 부처님께 시주하겠다고 약속했습니다. 눈을 뜰 수 있다는 말에 앞뒤를 가리지 않고 대답했지만, 쌀 서 되도 없는 형편에 삼백 석을 마련할 길이 없었고 부처님을 속인 셈이 되었기에 후회하며 앓아누웠습니다.","keywords":["공양미","약속"]},{"position":1,"type":"short_answer","prompt":"심청은 아버지에게 자신이 뱃사람들에게 몸을 팔았다는 사실을 곧바로 말하지 않고 무엇이라고 둘러댔나요? 그렇게 한 까닭은 무엇일까요?","sampleAnswer":"장 승상 댁 부인의 수양딸로 들어가게 되어 쌀 삼백 석을 받았다고 둘러댔습니다. 사실을 알면 아버지가 절대로 허락하지 않을 것이고, 남은 날을 슬픔 속에 살게 될 것을 걱정했기 때문입니다.","keywords":["수양딸","아버지"]},{"position":2,"type":"short_answer","prompt":"심청이 인당수에 빠진 뒤 다시 세상으로 돌아오는 과정은 현실에서 일어나기 어려운 일입니다. 작가는 왜 이런 비현실적인 이야기를 넣었을까요?","sampleAnswer":"현실에서는 착한 사람이 반드시 보상받지 못한다는 것을 사람들도 알고 있었습니다. 그래서 이야기 속에서만이라도 지극한 효성이 반드시 보답받기를 바라는 마음을 담아, 용궁과 연꽃이라는 환상적인 장치로 심청을 되살려 낸 것입니다.","keywords":["효","용궁"]},{"position":3,"type":"essay","prompt":"심청은 아버지를 위해 목숨을 내놓았습니다. 이 선택을 여러분은 어떻게 생각하나요? 효도라는 것이 이렇게까지 해야 하는 것인지, 아니면 다른 방법이 있었을지 자신의 생각을 써 보세요.","rubric":"찬성·반대에 정답은 없습니다. 자신의 입장을 분명히 밝히고, 작품 속 상황이나 오늘날의 가치관과 연결해 까닭을 설명했는지를 봅니다."}]'::jsonb
  WHERE slug = 'simcheong';

-- 심생전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"심생은 소녀의 집을 알아낸 뒤 무엇을 했나요? 그리고 소녀는 왜 서른 날이 지나서야 문을 열었나요?","sampleAnswer":"심생은 밤마다 그 집 담 밖에 서서 기다렸습니다. 비가 오나 바람이 부나 같은 자리에 섰고 그러기를 서른 날이 되었습니다. 소녀는 문을 열면 어떻게 되는지 이미 알고 있었기에 망설였으며, 심생을 시험한 것이 아니라 그 뒷일을 감당할 수 있을지 자기 자신을 시험한 것이라고 말했습니다.","keywords":["서른","담"]},{"position":1,"type":"short_answer","prompt":"두 집안 부모의 태도는 어떻게 달랐나요? 그리고 그 결과는 어떠했나요?","sampleAnswer":"소녀의 부모는 딸의 이야기를 끝까지 듣고 뜻을 막지 않되 뒷일을 감당해야 한다고 일렀습니다. 심생의 부모는 아들을 꾸짖거나 가두지 않고 북한산 절로 보내 과거 공부를 하게 했습니다. 어느 쪽도 모질게 굴지 않았지만, 결과적으로 두 사람은 영영 갈라지게 되었습니다.","keywords":["부모","과거"]},{"position":2,"type":"short_answer","prompt":"소녀가 남긴 편지에서 말한 ''담''은 무엇을 가리키나요? 그리고 그 말이 왜 중요한지 함께 써 보세요.","sampleAnswer":"양반과 중인을 가르는 신분의 벽을 가리킵니다. 심생은 담 밖에 서른 밤을 섰고 소녀는 문을 열어 두 사람 모두 할 수 있는 일을 다 했지만, 그 담은 사람 둘의 마음과 노력으로 없앨 수 있는 것이 아니었습니다. 개인의 잘못이 아니라 제도가 두 사람을 갈라놓았음을 보여 주기 때문에 중요합니다.","keywords":["신분","담"]},{"position":3,"type":"essay","prompt":"이 작품에는 미워할 만한 나쁜 사람이 하나도 나오지 않습니다. 그런데도 결말은 비극입니다. 악인이 없는 비극은 악인이 있는 비극과 어떻게 다르게 느껴지나요? 「장화홍련전」이나 「사씨남정기」와 견주어 자신의 생각을 써 보세요.","rubric":"갈등의 원인이 특정 인물이 아니라 제도에 있다는 점을 파악했는지, 악인이 있는 작품과 견주어 차이를 설명했는지, 그리고 자기 생각을 근거와 함께 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'simsaeng';

-- 소대성전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"''소대성이 모양 잠만 잔다''는 속담의 뜻을 쓰고, 소설에서 그 잠이 실제로 무엇이었는지 설명해 보세요.","sampleAnswer":"속담은 게으르게 잠만 자는 사람을 두고 하는 말입니다. 그러나 소설에서 대성의 잠은 게으름이 아니었습니다. 거지로 들어온 사위가 그 집에서 할 수 있는 일이 없었기 때문이고, 실제로 그는 집안 사정을 다 읽고 있어서 자객이 오기 전에 스스로 떠났습니다. 산에 들어간 뒤로는 새벽부터 밤까지 자지 않고 익혔습니다. 잠은 때를 기다리는 웅크림이었던 셈입니다.","keywords":["게으","잠"]},{"position":1,"type":"short_answer","prompt":"잠자는 대성을 두고 왕씨·채봉·이 상서는 각각 어떻게 반응하나요? 이 차이가 뜻하는 바를 써 보세요.","sampleAnswer":"왕씨는 게으른 거지로 보아 내쫓으려 하고, 채봉은 ''그냥 자는 것이 아니다''라고 하며, 이 상서는 처음부터 눈빛을 알아보고 집에 들였습니다. 같은 사람을 두고 셋이 전혀 다른 것을 보는 것으로, 사람은 보이는 대로가 아니라 보고 싶은 대로 본다는 것을 드러냅니다.","keywords":["왕씨","이 상서"]},{"position":2,"type":"short_answer","prompt":"「유충렬전」·「조웅전」에는 정한담·이두병 같은 원수가 있지만 이 작품에는 없습니다. 그 차이가 이야기를 어떻게 바꾸나요?","sampleAnswer":"원수가 없으므로 통쾌한 복수가 성립하지 않습니다. 대신 무시당하던 사람이 힘을 얻어 제 자리를 찾으러 돌아오는 회복의 이야기가 됩니다. 마지막에 왕씨를 처형하는 대신 절을 하는 결말도 그래서 가능합니다.","keywords":["복수","원수"]},{"position":3,"type":"essay","prompt":"대성은 자기를 죽이려 했던 왕씨에게 ''장모님, 그동안 평안하셨습니까''라고 인사합니다. 이것이 벌하는 것보다 나은 결말이라고 생각하나요? 자신의 생각을 써 보세요.","rubric":"벌하지 않는 결말이 만들어 내는 효과를 파악했는지, 그리고 자기 판단에 근거를 세웠는지를 봅니다. 어느 쪽을 고르든 정답으로 봅니다."}]'::jsonb
  WHERE slug = 'sodaeseong';

-- 숙향전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"''적강(謫降)''이란 무엇이며, 이 작품의 처음과 끝이 어떻게 짝을 이루는지 설명해 보세요.","sampleAnswer":"적강은 하늘에 있던 존재가 죄를 지어 인간 세상으로 내려오는 것을 말합니다. 이 작품은 소아와 태을이 천상에서 죄를 지어 내려오는 데서 시작해, 숙향과 이선이 지상의 고난과 부귀를 다 겪은 뒤 하늘로 올라가는 데서 끝납니다. 내려온 자리로 되돌아가면서 이야기가 원을 그리며 닫힙니다.","keywords":["적강","하늘"]},{"position":1,"type":"short_answer","prompt":"숙향이 겪는 고난을 차례대로 정리하고, 그때마다 누가 그를 도왔는지 짝지어 써 보세요.","sampleAnswer":"다섯 살에 부모와 헤어져 바위에 버려졌을 때는 사슴이 장 승상 댁으로 데려다주었고, 사향의 모함으로 쫓겨나 표진강에 몸을 던졌을 때는 용왕의 딸들이 건졌으며, 갈대밭 불길에 갇혔을 때는 화덕진군이 구했고, 갈 곳이 없을 때는 마고할미가 거두었습니다. 고난과 구원이 짝을 이루어 되풀이됩니다.","keywords":["사슴","마고할미"]},{"position":2,"type":"short_answer","prompt":"낙양 태수가 숙향을 매질하라 명하는 장면은 왜 이 작품에서 가장 얄궂은 대목이라 할 수 있나요?","sampleAnswer":"그 태수가 바로 스무 해 동안 딸을 찾아 헤맨 친아버지 김전이기 때문입니다. 아버지가 딸인 줄 모르고 딸을 죽이라 명하는 상황이 되지요. 관비의 팔이 굳어 형장을 내리치지 못하고, 어머니가 옥가락지를 알아보면서 비로소 진실이 드러납니다.","keywords":["김전","아버지"]},{"position":3,"type":"essay","prompt":"「홍계월전」의 계월은 싸워서 이기고, 숙향은 견디며 도움을 받습니다. 두 이야기 가운데 어느 쪽이 당시 여성 독자에게 더 큰 위로가 되었을지, 그리고 그렇게 생각하는 까닭은 무엇인지 써 보세요.","rubric":"두 작품의 주인공이 고난에 대응하는 방식의 차이를 정확히 짚었는지, 그리고 자기 판단에 대해 당시의 처지나 독자층을 근거로 든 이유를 세웠는지를 봅니다. 어느 쪽을 고르든 정답으로 봅니다."}]'::jsonb
  WHERE slug = 'sukhyang';

-- 숙영낭자전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"숙영이 죽음에 이르는 과정을 순서대로 정리하고, 각 단계에서 누가 무엇을 했는지 써 보세요.","sampleAnswer":"아버지의 권유로 선군이 과거를 보러 떠나고, 선군이 밤마다 몰래 돌아와 아내의 방에 듭니다. 그 소리를 들은 종 매월이 소문을 내고 사내를 사서 방 앞에서 뛰어나가게 합니다. 그 광경을 본 시아버지가 이튿날 며느리를 뜰에 세우고 종들 앞에서 매를 듭니다. 숙영은 옥비녀를 던져 결백을 증명하지만 그날 스스로 목숨을 끊습니다.","keywords":["매월","시아버지"]},{"position":1,"type":"short_answer","prompt":"옥비녀가 섬돌에 꽂혀 결백이 증명되었는데도 숙영은 왜 죽음을 택했을까요?","sampleAnswer":"결백이 밝혀졌다고 해서 이미 겪은 일이 사라지지는 않기 때문입니다. 종들 앞에 세워져 문초를 받았고, 시아버지가 자기를 그런 사람으로 여겼다는 사실은 그대로 남습니다. 그를 죽인 것은 누명 자체가 아니라 누명을 씌운 뒤의 그 시간이라고 볼 수 있습니다.","keywords":["결백","시아버지"]},{"position":2,"type":"short_answer","prompt":"이 작품에서 벌을 받은 사람은 매월뿐입니다. 그러나 책임이 매월에게만 있다고 보기는 어렵습니다. 왜 그런가요?","sampleAnswer":"매월은 소문을 내고 장면을 꾸몄을 뿐이고, 그것을 사실로 확정한 것은 시아버지 백상군입니다. 며느리의 말을 듣지 않았고, 아들이 돌아와 확인할 때까지 기다리지도 않았으며, 종들이 보는 앞에서 매를 들었습니다. 의심하는 것과 심판하는 것은 다르며, 매월의 계략은 벌할 수 있지만 묻지 않은 잘못은 벌할 데가 없습니다.","keywords":["소문","시아버지"]},{"position":3,"type":"essay","prompt":"이 작품은 죽은 숙영이 다시 살아나는 것으로 끝납니다. 이 결말을 어떻게 보나요? 억지스러운 마무리라고 생각하는지, 아니면 그렇게 끝낼 수밖에 없었다고 생각하는지 까닭과 함께 써 보세요.","rubric":"재생 결말이 다른 애정소설(이생규장전·만복사저포기)과 다르다는 점을 파악했는지, 그리고 그에 대한 자기 판단을 근거와 함께 세웠는지를 봅니다. 어느 쪽을 고르든 정답으로 봅니다."}]'::jsonb
  WHERE slug = 'sukyeong';

-- 토끼전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"별주부는 토끼를 어떻게 꾀어서 용궁으로 데려갔나요? 토끼가 그 말에 넘어간 까닭은 무엇인가요?","sampleAnswer":"수궁에는 사철 먹을 것이 넉넉하고 잡아먹으려는 짐승도 없으며 벼슬까지 얻게 해 주겠다고 꾀었습니다. 토끼는 뭍에서 뱀·사냥꾼·매에 쫓기며 굶주리는 신세였기 때문에 편안하고 배부른 삶을 바라 그 말에 넘어갔습니다.","keywords":["수궁","벼슬"]},{"position":1,"type":"short_answer","prompt":"죽을 위기에 놓인 토끼는 어떤 꾀를 내어 살아났나요?","sampleAnswer":"토끼 족속은 달마다 간을 꺼내 씻어 바위에 널어 두었다가 다시 넣는데, 마침 간을 산에 두고 왔다고 둘러댔습니다. 믿지 못하겠으면 배를 갈라 보라며 태연하게 큰소리를 쳐서 용왕이 이를 믿게 만들었고, 간을 가지러 간다는 구실로 뭍에 나와 달아났습니다.","keywords":["간","산"]},{"position":2,"type":"short_answer","prompt":"이 작품에서 용왕과 별주부, 토끼는 각각 어떤 사람들을 빗댄 것이라고 볼 수 있나요?","sampleAnswer":"용왕은 자기 목숨을 위해 남의 목숨을 함부로 요구하는 지배층을, 별주부는 그 명령이 옳은지 따지지 않고 충성만 다하는 신하를, 토끼는 힘은 없지만 지혜로 위기를 헤쳐 나가는 백성을 빗댄 것으로 볼 수 있습니다.","keywords":["용왕","백성"]},{"position":3,"type":"essay","prompt":"별주부는 용왕에게 충성하기 위해 죄 없는 토끼를 속여 데려왔습니다. 별주부의 행동을 어떻게 평가하나요? 윗사람의 명령이라면 무엇이든 따라야 하는지, 자신의 생각을 써 보세요.","rubric":"충성과 옳고 그름 사이의 긴장을 이해했는지, 자신의 입장을 밝히고 까닭을 작품이나 경험과 연결해 설명했는지를 봅니다."}]'::jsonb
  WHERE slug = 'tokki';

-- 운영전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"안평대군은 궁녀들에게 무엇을 해 주었고, 동시에 무엇을 금지했나요? 그 두 가지가 함께 있을 때 어떤 문제가 생기는지 써 보세요.","sampleAnswer":"궁녀 열 명을 뽑아 손수 글과 시를 가르쳐 주었지만, 궁 밖으로 나가거나 바깥 사람과 말을 나누는 것은 죽음으로 금했습니다. 재주는 길러 주고 그 재주를 쓸 자리는 막았기 때문에, 궁녀들은 배운 것을 어디에도 쓸 수 없는 처지에 놓이게 됩니다.","keywords":["궁녀","글"]},{"position":1,"type":"short_answer","prompt":"운영과 김 진사의 계획이 실패한 직접적인 원인은 무엇이었나요?","sampleAnswer":"김 진사의 종 특이 옮겨 달라고 맡긴 짐을 가로챈 뒤, 도리어 김 진사를 협박하고 소문까지 퍼뜨렸기 때문입니다. 돕는 척하며 다가왔던 사람의 배신으로 일이 드러나게 되었습니다.","keywords":["김 진사","배신"]},{"position":2,"type":"short_answer","prompt":"이 작품은 유영이라는 선비가 꿈에서 두 사람을 만나 이야기를 듣는 형식입니다. 이런 구성을 무엇이라 하며, 그렇게 쓴 효과는 무엇일까요?","sampleAnswer":"액자소설이라고 합니다. 이미 세상을 떠난 사람이 자기 이야기를 직접 들려줄 수 있게 되고, 깨어난 뒤 책 한 권이 남아 있어 그 이야기가 실제로 있었던 일처럼 느껴지는 효과가 있습니다.","keywords":["액자소설","이야기"]},{"position":3,"type":"essay","prompt":"자란은 ''죄가 있다면 사람의 마음을 가지고도 그것을 쓸 데가 없게 하신 데 있다''고 말합니다. 누군가에게 무언가를 배우게 해 놓고 그것을 펼칠 기회는 주지 않는 일이 오늘날에도 있을까요? 자신의 생각을 써 보세요.","rubric":"작품이 제기한 ''재주와 기회의 어긋남''이라는 문제를 이해했는지, 그리고 그것을 오늘의 현실이나 자신의 경험과 연결해 생각을 세웠는지를 봅니다."}]'::jsonb
  WHERE slug = 'unyeong';

-- 원생몽유록
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"몽유록의 세 단계를 쓰고, 이 작품에서 각 단계가 어느 대목에 해당하는지 짝지어 보세요.","sampleAnswer":"입몽·몽중·각몽입니다. 입몽은 원자허가 가을밤 옛일을 생각하다 잠드는 대목, 몽중은 복건 쓴 이를 따라 정자에 이르러 여섯 사람과 시를 주고받고 칼 찬 사내의 노래를 듣는 대목, 각몽은 바람이 일며 모든 것이 사라지고 제 방에서 눈을 뜨는 대목입니다.","keywords":["입몽","각몽"]},{"position":1,"type":"short_answer","prompt":"이 작품은 왜 실제 인물의 이름을 밝히지 않고 꿈의 형식을 빌렸을까요?","sampleAnswer":"다루는 사건이 어린 임금이 자리를 빼앗기고 죽은 일이라, 그것을 비판하는 것은 곧 나라를 세운 임금을 비난하는 일이 되어 처벌받을 수 있었기 때문입니다. 꿈은 스스로 꾸는 것이 아니라 찾아오는 것이므로, 문제가 되면 꿈 이야기일 뿐이라고 물러설 수 있습니다. 이름을 적지 않아도 독자는 누구인지 알아보므로 비판은 그대로 전달됩니다.","keywords":["꿈","임금"]},{"position":2,"type":"short_answer","prompt":"칼 찬 사내가 ''썩은 선비들과는 큰일을 도모할 수 없다''고 말했을 때 다섯 신하는 아무 대꾸도 하지 못합니다. 이 침묵은 무엇을 뜻할까요?","sampleAnswer":"그 말이 옳다는 것을 그들 자신도 알고 있기 때문입니다. 나아가 이 비판은 죽은 이들에게만 향하지 않고, 그 일을 알면서도 입을 다물고 있는 당대의 선비들, 곧 이 글을 읽는 독자에게까지 향합니다. 대꾸가 없는 자리에 독자가 놓이는 셈입니다.","keywords":["선비","독자"]},{"position":3,"type":"essay","prompt":"작품은 ''이것을 하늘의 뜻이라 해야 하오, 사람의 일이라 해야 하오''라는 물음으로 끝납니다. 옳은 사람이 옳게 하고도 지는 일을 어떻게 받아들여야 한다고 생각하나요? 자신의 생각을 써 보세요.","rubric":"작품이 답을 주지 않고 끝난다는 점을 파악했는지, 그리고 그 물음에 대해 자기 나름의 답을 근거와 함께 세웠는지를 봅니다. 어떤 답이든 정답으로 봅니다."}]'::jsonb
  WHERE slug = 'wonsaeng';

-- 양반전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"가난한 양반이 신분을 팔게 된 까닭은 무엇인가요?","sampleAnswer":"글 읽기만 좋아하고 살림을 꾸리지 못해 해마다 관아의 환곡을 빌려 먹다가, 갚지 못한 곡식이 천 석에 이르렀습니다. 관찰사가 이를 알고 잡아 가두라 명하자, 이를 갚아 주겠다는 부자에게 양반 신분을 팔게 되었습니다.","keywords":["환곡","부자"]},{"position":1,"type":"short_answer","prompt":"군수가 써 준 첫 번째 증서에는 어떤 내용이 담겨 있었나요? 그 내용을 읽은 부자는 왜 실망했나요?","sampleAnswer":"새벽에 일어나 앉아 있기, 추워도 불을 쬐지 않기, 국물을 소리 내어 마시지 않기, 돈을 손에 쥐지 않기 같은 형식적인 규범만 잔뜩 적혀 있었습니다. 부자는 양반이 되면 좋은 일이 많을 줄 알았는데 지켜야 할 불편한 규칙만 있고 아무 이득이 없어 실망했습니다.","keywords":["규칙","이득"]},{"position":2,"type":"short_answer","prompt":"부자가 두 번째 증서를 듣다가 ''나를 도둑놈으로 만들 작정이오?''라며 달아난 까닭은 무엇인가요?","sampleAnswer":"두 번째 증서에는 이웃의 소를 마음대로 끌어다 쓰고, 마을 사람을 불러 일을 시키고, 상민을 함부로 대해도 아무도 원망하지 못한다는 내용이 적혀 있었습니다. 부자는 그런 특권이 결국 남의 것을 빼앗는 도둑질과 다름없다고 느껴 양반 되기를 포기한 것입니다.","keywords":["도둑","특권"]},{"position":3,"type":"essay","prompt":"이 작품에서 부자는 돈으로 신분을 살 수 있었습니다. 오늘날에도 돈이 있으면 얻을 수 있는 것과, 돈으로는 살 수 없는 것이 있다고 생각하나요? 작품과 연결해 자신의 생각을 써 보세요.","rubric":"작품 속 신분 매매의 의미를 이해했는지, 그리고 그것을 오늘의 현실과 견주어 자기 생각을 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'yangban';

-- 예덕선생전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"제자 자목은 왜 스승을 떠나겠다고 했나요? 그가 문제 삼은 것이 무엇이었는지 정확히 써 보세요.","sampleAnswer":"스승이 저잣거리에서 똥을 지는 엄 행수를 ''선생''이라 부르며 벗하는 것이 남 보기 부끄러웠기 때문입니다. 자목은 엄 행수를 만난 적도 없으므로 그 사람됨을 문제 삼은 것이 아니라, 오직 그가 하는 일이 천하다는 이유만으로 부끄러워한 것입니다.","keywords":["엄 행수","부끄"]},{"position":1,"type":"short_answer","prompt":"선귤자는 세상 사람들의 사귐을 어떻게 비판했나요?","sampleAnswer":"부유한 사람과 사귀는 자는 재물을 바라고 권세 있는 사람과 사귀는 자는 그 힘을 바라며, 얼굴을 마주하면 웃고 돌아서면 흉을 본다고 했습니다. 또 아첨에는 몸을 낮춰 아양 떠는 것, 좋은 말로 치켜세우는 것, 상대가 싫어하는 것을 미리 피하는 것 세 가지가 있다며, 그런 것을 사귐이라 한다면 차라리 사귀지 않겠다고 했습니다.","keywords":["재물","아첨"]},{"position":2,"type":"short_answer","prompt":"''똥은 더럽지만 그것으로 곡식을 기른다''는 말 뒤에 선귤자는 무엇을 물었나요? 그 물음이 겨누는 대상을 함께 써 보세요.","sampleAnswer":"''더럽지 않은 척하며 백성을 쥐어짜는 자들은 무엇을 기르느냐''고 물었습니다. 관을 쓰고 띠를 두르고 앉아 남의 것을 빼앗는 자들, 곧 겉은 깨끗해 보이지만 하는 일은 수탈인 지배층을 겨눈 물음입니다.","keywords":["백성","지배층"]},{"position":3,"type":"essay","prompt":"이 작품에서 주인공 엄 행수는 한 번도 직접 등장하지 않고, 오직 스승이 전하는 말로만 그려집니다. 작가는 왜 이런 방식을 택했을까요? 그리고 오늘날에도 ''하는 일''로 사람을 판단하는 일이 있다고 생각하는지 함께 써 보세요.","rubric":"간접 제시라는 방법과 그 효과를 생각해 보았는지, 그리고 직업으로 사람을 평가하는 문제를 오늘의 현실과 연결해 자기 생각을 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'yedeok';

-- 용궁부연록
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"용왕은 한생을 왜 용궁으로 불렀나요? 그리고 한생이 지은 글을 읽은 용왕은 어떻게 했나요?","sampleAnswer":"딸의 혼인을 위해 새로 지은 가회각에 걸 상량문을 지어 달라고 불렀습니다. 물속에는 그 글을 지을 만한 사람이 없었기 때문입니다. 한생이 단숨에 써 내려간 글을 읽은 용왕은 자리에서 일어나 절을 하며 참으로 귀한 것을 얻었다고 했습니다.","keywords":["상량문","용왕"]},{"position":1,"type":"short_answer","prompt":"''이 자리에서는 글이 곧 지위''라는 용왕의 말은 무엇을 뜻하나요? 인간 세상과 견주어 설명해 보세요.","sampleAnswer":"용궁에서는 신분이나 벼슬이 아니라 글재주에 따라 자리가 정해진다는 뜻입니다. 인간 세상에서는 글을 아무리 잘 지어도 벼슬이 없으면 아랫자리에 앉아야 했으므로, 용궁은 그 순서가 뒤집힌 곳입니다.","keywords":["글재주","벼슬"]},{"position":2,"type":"short_answer","prompt":"용궁에 다녀온 뒤 한생의 삶은 어떻게 달라졌나요? 그 변화가 뜻하는 바를 함께 써 보세요.","sampleAnswer":"받은 야광주와 비단을 상자에 넣어 두고 남에게 보이지도 팔지도 않았으며, 벼슬을 구하지 않고 이름을 다투지 않았고 글을 청해도 붓을 들지 않다가 산으로 들어가 자취를 감췄습니다. 자기 재주가 제대로 대접받는 세상을 한번 보고 나니, 그렇지 않은 이 세상에서 더는 자리를 다툴 마음이 없어졌다는 뜻으로 볼 수 있습니다.","keywords":["벼슬","산"]},{"position":3,"type":"essay","prompt":"「금오신화」 다섯 편의 주인공은 모두 이 세상에 자리를 얻지 못하고 다른 곳으로 갑니다. 다섯 살에 신동으로 불렸으나 평생 벼슬을 마다하고 떠돈 김시습의 삶과 겹쳐, 그가 왜 이런 결말을 되풀이해 썼을지 자신의 생각을 써 보세요.","rubric":"다섯 편의 공통된 결말 구조를 파악했는지, 작가의 삶과 연결해 해석했는지, 그리고 자기 생각을 근거와 함께 세웠는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'yonggung';

-- 유충렬전
UPDATE public.works SET questions = '[{"position":0,"type":"short_answer","prompt":"유심이 귀양을 가게 된 까닭은 무엇인가요? 그리고 그 뒤 충렬과 어머니에게는 어떤 일이 일어났나요?","sampleAnswer":"정한담이 남쪽 정벌을 주장하자 유심이 백성이 굶주리고 창고가 비었다며 반대했고, 이에 앙심을 품은 정한담과 최일귀가 유심이 딴마음을 품었다고 거짓으로 아뢰어 귀양을 보냈습니다. 이어 정한담이 사람을 보내 집에 불을 지르자 어머니는 충렬을 업고 달아났으나, 강가에서 사람을 잡아 파는 자들에게 붙들려 끌려가고 일곱 살 충렬은 홀로 남겨졌습니다.","keywords":["정한담","귀양"]},{"position":1,"type":"short_answer","prompt":"이 작품의 줄거리를 ''영웅의 일대기 구조''에 따라 다섯 단계로 정리해 보세요.","sampleAnswer":"① 하늘의 신하가 내려온다는 태몽과 함께 비범하게 태어남 ② 간신의 모함으로 집안이 무너져 일곱 살에 부모와 헤어지고 빌어먹으며 떠도는 시련 ③ 강희주에게 거두어지고 백룡사 노승에게 무예와 병법, 갑옷·보검·천리마를 얻어 힘을 기름 ④ 정한담이 오랑캐와 손잡아 도성이 함락되고 임금이 항복 직전에 놓이는 위기 ⑤ 나타나 적을 물리치고 정한담을 사로잡은 뒤 흩어졌던 가족을 모두 되찾음.","keywords":["태몽","정한담"]},{"position":2,"type":"short_answer","prompt":"작가는 왜 하필 임금이 항복 문서에 붓을 대려는 순간에 유충렬을 등장시켰을까요? 당시의 역사와 연결해 써 보세요.","sampleAnswer":"실제 병자호란에서 인조는 삼전도에서 청나라에 항복했고, 임진왜란 때도 임금이 도성을 버리고 피란했습니다. 백성들에게 그것은 씻기 어려운 치욕이었습니다. 이야기는 바로 그 장면 직전에 영웅을 나타나게 함으로써, 현실에서 겪은 패배를 이야기 속에서나마 되돌리고 답답함을 풀어 준 것입니다.","keywords":["병자호란","항복"]},{"position":3,"type":"essay","prompt":"이 작품에서 나라를 위태롭게 한 것은 바깥의 오랑캐만이 아니라 안에서 문을 열어 준 정한담, 그리고 간신의 말을 믿은 임금이었습니다. 어떤 공동체가 어려움에 빠질 때 그 원인을 밖에서 찾는 것과 안에서 찾는 것은 어떻게 다를까요? 자신의 생각을 써 보세요.","rubric":"작품이 갈등의 원인을 내부에 두고 있다는 점을 파악했는지, 그리고 그 시각의 의미를 자기 생각이나 경험과 연결해 설명했는지를 봅니다. 특정한 정답은 없습니다."}]'::jsonb
  WHERE slug = 'yuchungnyeol';

-- 확인: 낱말이 들어간 문항 수
SELECT COUNT(*) AS 낱말있는문항
FROM public.works w, jsonb_array_elements(w.questions) AS x
WHERE jsonb_array_length(COALESCE(x->'keywords', '[]'::jsonb)) > 0;
